import React, { useRef } from 'react';
import { Button, styled } from '@mui/material';
import Papa from 'papaparse';

const StyledButton = styled(Button)(({ theme }) => ({
  backgroundColor: '#00DE93',
  color: '#ffffff',
  padding: theme.spacing(1, 3),
  borderRadius: '8px',
  textTransform: 'none',
  fontWeight: 500,
  boxShadow: theme.shadows[2],
  transition: 'all 0.3s ease',
  '&:hover': {
    backgroundColor: '#00c17c',
    boxShadow: theme.shadows[4],
    transform: 'translateY(-1px)',
  },
}));

function UploadButton({ onFileUpload }) {
  const inputRef = useRef(null);

  const handleFileChange = async (event) => {
    const files = Array.from(event.target.files);
    if (files.length === 0) return;

    const fileNames = files.map(file => file.name);
    const plotPanels = [];
    const fileLabelMap = {}; // Map fileName to its label (concentration or numeric tag)
    let unknownCounter = 1; // Counter for files with "unknown" concentration

    for (const file of files) {
      const result = await new Promise((resolve) => {
        Papa.parse(file, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => resolve(results),
          error: (error) => {
            console.error('Error parsing CSV:', error);
            resolve(null);
          },
        });
      });

      if (!result || !result.data || result.data.length === 0) continue;

      const data = result.data;
      const concentrationMatch = file.name.match(/(\d+(\.\d+)?)(nL|uL|ppm)/);
      const concentration = concentrationMatch ? concentrationMatch[0] : 'unknown';

      // Assign label: use concentration if available, otherwise use a numeric tag
      if (concentration === 'unknown') {
        fileLabelMap[file.name] = `${unknownCounter}`;
        unknownCounter++;
      } else {
        fileLabelMap[file.name] = concentration;
      }

      const allColumns = {};
      Object.keys(data[0]).forEach(key => {
        allColumns[key] = data.map(row => {
          const value = parseFloat(row[key]);
          return isNaN(value) ? 0 : value;
        });
      });

      const time = allColumns['time'] || allColumns['Time'] || Array.from({ length: data.length }, (_, i) => i + 1);

      Object.keys(allColumns).forEach(key => {
        const isSupportedColumn = key.startsWith('CHR') ||
          /^s\d{1,2}$/.test(key) ||
          /^Sensor\d{2}-dVal$/.test(key) ||
          /^S\d{1,2}$/.test(key);

        if (isSupportedColumn) {
          const existingPanel = plotPanels.find(panel => panel.key === key);
          const trial = { time, allColumns, fileName: file.name, label: fileLabelMap[file.name] }; // Add label to trial

          if (existingPanel) {
            if (existingPanel.fileGroups[concentration]) {
              existingPanel.fileGroups[concentration].push(trial);
            } else {
              existingPanel.fileGroups[concentration] = [trial];
            }
          } else {
            plotPanels.push({
              key,
              fileGroups: {
                [concentration]: [trial],
              },
            });
          }
        }
      });
    }

    if (plotPanels.length > 0) {
      onFileUpload(plotPanels, fileNames, fileLabelMap);
    } else {
      console.warn('No supported columns found in uploaded files');
    }

    inputRef.current.value = '';
  };

  return (
    <StyledButton
      variant="contained"
      component="label"
    >
      Upload CSV Files
      <input
        ref={inputRef}
        type="file"
        accept=".csv"
        multiple
        hidden
        onChange={handleFileChange}
      />
    </StyledButton>
  );
}

export default UploadButton;