/* global Plotly */
import React, { useEffect, useRef } from 'react';
import { Box } from '@mui/material';
import { mean, movingAverage, savitzkyGolay, medianFilter } from '../utils/utils';

function PlotGrid({ plots, timeStart, timeEnd, noiseFilter, windowSize, polynomialOrder, baselineStart, baselineEnd, showRaw }) {
  const plotRefs = useRef(plots.map(() => React.createRef()));

  useEffect(() => {
    if (!window.Plotly) return;

    plots.forEach((plot, index) => {
      const { key, fileGroups } = plot;
      const plotRef = plotRefs.current[index];

      const traces = [];
      let isNormalized = false;

      // Define a color palette for different files
      const colorPalette = [
        '#1f77b4', // Blue
        '#ff7f0e', // Orange
        '#2ca02c', // Green
        '#d62728', // Red
        '#9467bd', // Purple
        '#8c564b', // Brown
        '#e377c2', // Pink
        '#7f7f7f', // Gray
      ];

      // Map file names to colors
      const fileColorMap = {};
      let colorIndex = 0;
      Object.values(fileGroups).forEach(trials => {
        trials.forEach(trial => {
          if (!fileColorMap[trial.fileName]) {
            fileColorMap[trial.fileName] = colorPalette[colorIndex % colorPalette.length];
            colorIndex++;
          }
        });
      });

      Object.entries(fileGroups).forEach(([_, trials]) => {
        trials.forEach(trial => {
          const values = trial.allColumns[key];
          if (!values || values.length === 0) {
            console.warn(`No valid data for column ${key} in file ${trial.fileName}`);
            return;
          }

          // Convert string values to numbers, default to 0 if not a valid number
          const cleanedValues = values.map(val => {
            const num = parseFloat(val);
            return isNaN(num) ? 0 : num;
          });

          let times = Array.from({ length: trial.time.length }, (_, i) => i + 1);
          let filteredValues = cleanedValues;
          let traceTimes = times;
          let traceValues = cleanedValues;

          // Time Range Filtering
          if (timeStart !== null && timeEnd !== null) {
            const indicesInRange = times
              .map((t, i) => ({ time: t, index: i }))
              .filter(t => t.time >= timeStart && t.time <= timeEnd)
              .map(t => t.index);

            if (indicesInRange.length === 0) {
              console.warn(`No data points in time range ${timeStart}-${timeEnd} for ${key} in file ${trial.fileName}`);
              return;
            }

            traceTimes = indicesInRange.map(i => times[i]);
            filteredValues = indicesInRange.map(i => cleanedValues[i]);
            traceValues = filteredValues;
          }

          let baselineAvg = 0;
          isNormalized = false;

          // Baseline Normalization
          if (baselineStart !== null && baselineEnd !== null && baselineStart <= baselineEnd) {
            const baselineIndices = traceTimes
              .map((t, i) => ({ time: t, index: i }))
              .filter(t => t.time >= baselineStart && t.time <= baselineEnd)
              .map(t => t.index);

            if (baselineIndices.length > 0) {
              const baselineValues = filteredValues.filter((_, i) => baselineIndices.includes(i));
              baselineAvg = baselineValues.reduce((sum, val) => sum + val, 0) / baselineValues.length;
              if (baselineAvg !== 0) {
                filteredValues = filteredValues.map(y => 100 * (y - baselineAvg) / baselineAvg);
                isNormalized = true;
              } else {
                console.warn(`Baseline average is 0 for ${key} in file ${trial.fileName}; normalization skipped`);
              }
            } else {
              console.warn(`No data points in baseline range ${baselineStart}-${baselineEnd} for ${key} in file ${trial.fileName}`);
            }
          }

          // Noise Filtering
          if (isNormalized && noiseFilter !== 'none') {
            try {
              if (noiseFilter === 'movingAverage') {
                filteredValues = movingAverage(filteredValues, windowSize);
              } else if (noiseFilter === 'savitzkyGolay') {
                filteredValues = savitzkyGolay(filteredValues, windowSize, polynomialOrder);
              } else if (noiseFilter === 'medianFilter') {
                filteredValues = medianFilter(filteredValues, windowSize);
              }
            } catch (error) {
              console.error(`Error applying noise filter ${noiseFilter} for ${key} in file ${trial.fileName}:`, error);
              return;
            }
          }

          const fileColor = fileColorMap[trial.fileName];

          if (isNormalized) {
            // Plot filtered data
            traces.push({
              x: traceTimes,
              y: filteredValues,
              type: 'scatter',
              mode: 'lines',
              name: `${trial.label} (Filtered)`,
              line: { color: fileColor },
            });

            // Plot raw data if showRaw is true
            if (showRaw && baselineAvg !== 0) {
              const normalizedRaw = traceValues.map(y => 100 * (y - baselineAvg) / baselineAvg);
              traces.push({
                x: traceTimes,
                y: normalizedRaw,
                type: 'scatter',
                mode: 'lines',
                name: `${trial.label} (Raw)`,
                opacity: 0.3,
                line: { color: fileColor },
              });
            }
          } else {
            // Plot raw data
            traces.push({
              x: traceTimes,
              y: traceValues,
              type: 'scatter',
              mode: 'lines',
              name: `${trial.label} (Raw)`,
              line: { color: fileColor },
            });
          }
        });
      });

      if (traces.length === 0) {
        console.warn(`No traces to plot for ${key} after applying filters`);
        return;
      }

      // Calculate the Y-axis range to restrict to 80% of the plot's vertical range
      let minY = Infinity;
      let maxY = -Infinity;
      traces.forEach(trace => {
        const yValues = trace.y;
        const traceMinY = Math.min(...yValues);
        const traceMaxY = Math.max(...yValues);
        minY = Math.min(minY, traceMinY);
        maxY = Math.max(maxY, traceMaxY);
      });

      // Ensure minY and maxY are valid numbers
      if (!isFinite(minY) || !isFinite(maxY) || minY === maxY) {
        minY = minY === maxY ? minY - 1 : -1;
        maxY = minY === maxY ? maxY + 1 : 1;
      }

      // Calculate the full range and restrict to 80% at the top
      const fullRange = maxY - minY;
      const newMaxY = minY + (fullRange / 0.8); // Extend the range so the data occupies 80% of the vertical space

      const layout = {
        title: key,
        xaxis: {
          title: {
            text: 'Time',
            font: { size: 14 },
            standoff: 10,
          },
          showline: true,
          linewidth: 1,
          linecolor: '#666',
          mirror: true,
        },
        yaxis: {
          title: {
            text: isNormalized ? 'dR/R (%)' : key,
            font: { size: 14 },
            standoff: 10,
          },
          range: [minY, newMaxY], // Restrict Y-axis to leave 20% space at the top
          showline: true,
          linewidth: 1,
          linecolor: '#666',
          mirror: true,
        },
        margin: { t: 50, b: 70, l: 70, r: 50 },
        showlegend: true,
        legend: {
          orientation: 'h',
          x: 0,           // Position at the left edge
          y: 1,           // Position at the top inside the plot area
          xanchor: 'left', // Anchor the left side of the legend
          yanchor: 'top', // Anchor the top of the legend
          bgcolor: 'rgba(255, 255, 255, 0.8)',
          bordercolor: '#666',
          borderwidth: 1,
          font: { size: 12 },
        },
      };

      Plotly.newPlot(plotRef.current, traces, layout, { displayModeBar: false });
    });

    return () => {
      plots.forEach((_, index) => {
        if (plotRefs.current[index].current) {
          Plotly.purge(plotRefs.current[index].current);
        }
      });
    };
  }, [plots, timeStart, timeEnd, noiseFilter, windowSize, polynomialOrder, baselineStart, baselineEnd, showRaw]);

  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: 'repeat(3, minmax(0, 500px))',
        gap: 0.5,
        maxWidth: '1508px',
        mx: 'auto',
        width: '100%',
      }}
    >
      {plots.map((plot, index) => (
        <Box
          key={plot.key}
          ref={plotRefs.current[index]}
          sx={{
            width: '100%',
            maxWidth: '500px',
            height: '400px',
            bgcolor: '#fff',
            borderRadius: '8px',
            boxShadow: 2,
            boxSizing: 'border-box',
            overflow: 'hidden',
          }}
        />
      ))}
    </Box>
  );
}

export default PlotGrid;