import React from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography, Box, Button } from '@mui/material';

function ParametersTable({ parametersByFile }) {
  if (!parametersByFile || parametersByFile.length === 0) {
    return null;
  }

  // Function to generate timestamp in YYYYMMDDHHMMSS format
  const generateTimestamp = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}${month}${day}${hours}${minutes}${seconds}`;
  };

  // Function to convert table data to CSV and trigger download
  const downloadCSV = (parameters, concentration, originalFileName) => {
    // Define the CSV header with the new column
    const headers = ['CHR', 'Concentration', 'Max ΔR/R (%)', 'Rise Time (s)', 'Decay Time (s)', 'H0 (if available)', 'T0 (if available)', 'Original File Name'];
    
    // Convert parameters to CSV rows
    const rows = parameters.map(param => [
      param.chr,
      param.concentration,
      typeof param.maxDeltaR === 'number' ? param.maxDeltaR.toFixed(2) : 'N/A',
      typeof param.riseTime === 'number' ? param.riseTime.toFixed(2) : 'N/A',
      typeof param.decayTime === 'number' ? param.decayTime.toFixed(2) : 'N/A',
      typeof param.h0 === 'number' ? param.h0.toFixed(2) : 'N/A',
      typeof param.t0 === 'number' ? param.t0.toFixed(2) : 'N/A',
      originalFileName, // Add the original file name to each row
    ]);

    // Combine headers and rows into CSV content
    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    // Create a Blob with the CSV content
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    
    // Generate timestamp and create file name
    const timestamp = generateTimestamp();
    const downloadFileName = `${timestamp}_${concentration}_features.csv`;

    // Create a temporary link to trigger the download
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', downloadFileName);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Box sx={{ mt: 4, mb: 4, width: '100%', maxWidth: 800, mx: 'auto' }}>
      {parametersByFile.map((fileParams, index) => (
        <Box key={index} sx={{ mb: 4 }}>
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#333' }}>
              Parameters for {fileParams.concentration}
            </Typography>
            <Button
              variant="outlined"
              size="small"
              onClick={() => downloadCSV(fileParams.parameters, fileParams.concentration, fileParams.originalFileName)}
              sx={{ ml: 2, textTransform: 'none', borderColor: '#4caf50', color: '#4caf50', '&:hover': { borderColor: '#388e3c', color: '#388e3c' } }}
            >
              Download Table (CSV)
            </Button>
          </Box>
          <TableContainer component={Paper} sx={{ boxShadow: 2, borderRadius: '8px' }}>
            <Table sx={{ minWidth: 650 }} aria-label={`parameters table for ${fileParams.concentration}`}>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>CHR</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>Concentration</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>Max ΔR/R (%)</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>Rise Time (s)</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>Decay Time (s)</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>H0 (if available)</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>T0 (if available)</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {fileParams.parameters.map((param, paramIndex) => (
                  <TableRow key={paramIndex} sx={{ '&:nth-of-type(odd)': { bgcolor: '#fafafa' } }}>
                    <TableCell>{param.chr}</TableCell>
                    <TableCell>{param.concentration}</TableCell>
                    <TableCell>{typeof param.maxDeltaR === 'number' ? param.maxDeltaR.toFixed(2) : 'N/A'}</TableCell>
                    <TableCell>{typeof param.riseTime === 'number' ? param.riseTime.toFixed(2) : 'N/A'}</TableCell>
                    <TableCell>{typeof param.decayTime === 'number' ? param.decayTime.toFixed(2) : 'N/A'}</TableCell>
                    <TableCell>{typeof param.h0 === 'number' ? param.h0.toFixed(2) : 'N/A'}</TableCell>
                    <TableCell>{typeof param.t0 === 'number' ? param.t0.toFixed(2) : 'N/A'}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Box>
      ))}
    </Box>
  );
}

export default ParametersTable;