import React from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography, Box, Button } from '@mui/material';

function HumiditySensitivityTable({ results, errorMessage }) {
  if (errorMessage) {
    return (
      <Box sx={{ mt: 4, mb: 4, width: '100%', maxWidth: 800, mx: 'auto' }}>
        <Typography variant="h6" gutterBottom align="center" sx={{ fontWeight: 'bold', color: '#d32f2f' }}>
          {errorMessage}
        </Typography>
      </Box>
    );
  }

  if (!results || results.length === 0) {
    return null;
  }

  // Function to generate timestamp in YYYYMMDDHHMMSS format
  const generateTimestamp = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}${month}${day}${hours}${minutes}${seconds}`;
  };

  // Function to convert table data to CSV and trigger download
  const downloadCSV = () => {
    // Define the CSV header
    const headers = ['CHR', 'Concentration', '(ΔR/R)/ΔH (% Resistance Change / Unit H₀)', 'Original File Name'];
    
    // Convert results to CSV rows
    const rows = results.map(result => [
      result.chr,
      result.concentration,
      typeof result.slope === 'number' ? result.slope.toFixed(4) : 'N/A',
      result.originalFileName,
    ]);

    // Combine headers and rows into CSV content
    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    // Create a Blob with the CSV content
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    
    // Generate timestamp and create file name
    const timestamp = generateTimestamp();
    const downloadFileName = `${timestamp}_humidity_sensitivity.csv`;

    // Create a temporary link to trigger the download
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', downloadFileName);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Box sx={{ mt: 4, mb: 4, width: '100%', maxWidth: 800, mx: 'auto' }}>
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#333' }}>
          Humidity Sensitivity Results
        </Typography>
        <Button
          variant="outlined"
          size="small"
          onClick={downloadCSV}
          sx={{ ml: 2, textTransform: 'none', borderColor: '#4caf50', color: '#4caf50', '&:hover': { borderColor: '#388e3c', color: '#388e3c' } }}
        >
          Download Table (CSV)
        </Button>
      </Box>
      <TableContainer component={Paper} sx={{ boxShadow: 2, borderRadius: '8px' }}>
        <Table sx={{ minWidth: 650 }} aria-label="humidity sensitivity table">
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>CHR</TableCell>
              <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>Concentration</TableCell>
              <TableCell sx={{ fontWeight: 'bold', bgcolor: '#f5f5f5' }}>(ΔR/R)/ΔH (% Resistance Change / Unit H₀)</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {results.map((result, index) => (
              <TableRow key={index} sx={{ '&:nth-of-type(odd)': { bgcolor: '#fafafa' } }}>
                <TableCell>{result.chr}</TableCell>
                <TableCell>{result.concentration}</TableCell>
                <TableCell>{typeof result.slope === 'number' ? result.slope.toFixed(4) : 'N/A'}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
}

export default HumiditySensitivityTable;