import React, { useState, useEffect } from 'react';
import { Box, Typography, Button, TextField, styled } from '@mui/material';
import { ThemeProvider } from '@mui/material/styles';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faFileCsv } from '@fortawesome/free-solid-svg-icons';
import Navbar from './components/Navbar';
import UploadButton from './components/UploadButton';
import PlotGrid from './components/PlotGrid';
import TimeFilter from './components/TimeFilter';
import ParametersTable from './components/ParametersTable';
import HumiditySensitivityTable from './components/HumiditySensitivityTable';
import BaselineResistanceChart from './components/BaselineResistanceChart';
import Documents from './components/Documents';
import theme from './theme';
import { mean, movingAverage, savitzkyGolay, medianFilter } from './utils/utils';

const BaselineButton = styled(Button)(({ theme }) => ({
  backgroundColor: '#2196f3',
  color: '#ffffff',
  padding: theme.spacing(1, 2),
  borderRadius: '8px',
  textTransform: 'none',
  fontWeight: 500,
  boxShadow: theme.shadows[2],
  transition: 'all 0.3s ease',
  '&:hover': {
    backgroundColor: '#1976d2',
    boxShadow: theme.shadows[4],
    transform: 'translateY(-1px)',
  },
}));

function App() {
  const [tabValue, setTabValue] = useState(0);
  const [plots, setPlots] = useState([]);
  const [timeStart, setTimeStart] = useState(null);
  const [timeEnd, setTimeEnd] = useState(null);
  const [originalPlots, setOriginalPlots] = useState([]);
  const [noiseFilter, setNoiseFilter] = useState('none');
  const [windowSize, setWindowSize] = useState(5);
  const [polynomialOrder, setPolynomialOrder] = useState(2);
  const [baselineStart, setBaselineStart] = useState(null);
  const [baselineEnd, setBaselineEnd] = useState(null);
  const [normalizationApplied, setNormalizationApplied] = useState(false);
  const [showRaw, setShowRaw] = useState(true);
  const [startInput, setStartInput] = useState('');
  const [endInput, setEndInput] = useState('');
  const [filterTypeInput, setFilterTypeInput] = useState('none');
  const [windowSizeInput, setWindowSizeInput] = useState(5);
  const [polynomialOrderInput, setPolynomialOrderInput] = useState(2);
  const [baselineStartInput, setBaselineStartInput] = useState('');
  const [baselineEndInput, setBaselineEndInput] = useState('');
  const [baselineWindowStart, setBaselineWindowStart] = useState('');
  const [baselineWindowEnd, setBaselineWindowEnd] = useState('');
  const [uploadedFileNames, setUploadedFileNames] = useState([]);
  const [fileLabelMap, setFileLabelMap] = useState({});
  const [parametersByFile, setParametersByFile] = useState([]);
  const [showTable, setShowTable] = useState(false);
  const [humidityResults, setHumidityResults] = useState([]);
  const [humidityError, setHumidityError] = useState(null);
  const [showHumidityTable, setShowHumidityTable] = useState(false);
  const [isPlotlyLoaded, setIsPlotlyLoaded] = useState(false);
  const [showBaselineChart, setShowBaselineChart] = useState(false);

  // Load Plotly core via CDN
  useEffect(() => {
    const loadPlotly = () => {
      const script = document.createElement('script');
      script.src = 'https://cdn.plot.ly/plotly-2.35.2.min.js';
      script.async = true;
      script.onload = () => {
        console.log('Plotly loaded successfully');
        setIsPlotlyLoaded(true);
      };
      script.onerror = () => {
        console.error('Failed to load Plotly');
        setIsPlotlyLoaded(false);
      };
      document.body.appendChild(script);

      return () => {
        document.body.removeChild(script);
      };
    };

    loadPlotly();
  }, []);

  const handleTabChange = (event, newValue) => {
    console.log('Tab changed to:', newValue);
    setTabValue(newValue);
    setShowTable(false);
    setShowHumidityTable(false);
    setShowBaselineChart(false);
  };

  const handleFileUpload = (plotPanels, fileNames, fileLabelMap) => {
    console.log('Uploaded plots:', plotPanels);
    setPlots(plotPanels);
    setOriginalPlots(plotPanels);
    setTimeStart(null);
    setTimeEnd(null);
    setNoiseFilter('none');
    setWindowSize(5);
    setPolynomialOrder(2);
    setBaselineStart(null);
    setBaselineEnd(null);
    setNormalizationApplied(false);
    setShowRaw(true);
    setStartInput('');
    setEndInput('');
    setFilterTypeInput('none');
    setWindowSizeInput(5);
    setPolynomialOrderInput(2);
    setBaselineStartInput('');
    setBaselineEndInput('');
    setBaselineWindowStart('');
    setBaselineWindowEnd('');
    setUploadedFileNames(fileNames);
    setFileLabelMap(fileLabelMap);
    setParametersByFile([]);
    setShowTable(false);
    setShowHumidityTable(false);
    setShowBaselineChart(false);
    setHumidityResults([]);
    setHumidityError(null);
  };

  const handleFilter = (start, end, filterType, winSize, polyOrder, baselineStartNum, baselineEndNum) => {
    console.log('Filter applied:', { start, end, filterType, winSize, polyOrder, baselineStartNum, baselineEndNum });
    setTimeStart(start);
    setTimeEnd(end);
    setNoiseFilter(filterType);
    setWindowSize(winSize);
    setPolynomialOrder(polyOrder);
    setBaselineStart(baselineStartNum);
    setBaselineEnd(baselineEndNum);
    if (baselineStartNum !== null && baselineEndNum !== null && baselineStartNum <= baselineEndNum) {
      setNormalizationApplied(true);
    }
    setParametersByFile([]);
    setShowTable(false);
    setShowHumidityTable(false);
    setHumidityResults([]);
    setHumidityError(null);
  };

  const handleReset = () => {
    console.log('Reset filters');
    setTimeStart(null);
    setTimeEnd(null);
    setNoiseFilter('none');
    setWindowSize(5);
    setPolynomialOrder(2);
    setBaselineStart(null);
    setBaselineEnd(null);
    setNormalizationApplied(false);
    setShowRaw(true);
    setPlots(originalPlots);
    setStartInput('');
    setEndInput('');
    setFilterTypeInput('none');
    setWindowSizeInput(5);
    setPolynomialOrderInput(2);
    setBaselineStartInput('');
    setBaselineEndInput('');
    setBaselineWindowStart('');
    setBaselineWindowEnd('');
    setUploadedFileNames([]);
    setFileLabelMap({});
    setParametersByFile([]);
    setShowTable(false);
    setShowHumidityTable(false);
    setShowBaselineChart(false);
    setHumidityResults([]);
    setHumidityError(null);
  };

  const handleToggleRaw = () => {
    setShowRaw(prev => !prev);
  };

  const handleExtractParamsToggle = () => {
    if (!showTable) {
      if (!plots || plots.length === 0) {
        alert('No data available to extract parameters.');
        return;
      }

      if (timeStart === null || timeEnd === null) {
        alert('Please specify a time range to extract parameters.');
        return;
      }

      const paramsByFile = [];

      // Group trials by fileName
      const trialsByFile = {};
      uploadedFileNames.forEach(fileName => {
        trialsByFile[fileName] = {
          fileName: fileName,
          label: fileLabelMap[fileName] || '',
          trials: [],
        };
      });

      plots.forEach(plot => {
        Object.entries(plot.fileGroups).forEach(([_, trials]) => {
          trials.forEach(trial => {
            if (trialsByFile[trial.fileName]) {
              trialsByFile[trial.fileName].trials.push({
                key: plot.key,
                trial: trial,
              });
            }
          });
        });
      });

      // Extract parameters for each file
      Object.values(trialsByFile).forEach(fileData => {
        const { fileName, label, trials } = fileData;
        if (trials.length === 0) return;

        const parameters = [];

        trials.forEach(({ key, trial }) => {
          const isSupportedColumn = key.startsWith('CHR') ||
            /^s\d{1,2}$/.test(key) ||
            /^Sensor\d{2}-dVal$/.test(key) ||
            /^Sensor\d{2}-DR\d{1,2}$/.test(key) ||
            /^S\d{1,2}$/.test(key);
          if (!isSupportedColumn) return;

          const values = trial.allColumns[key];
          if (!values || values.length === 0) return;

          const cleanedValues = values.map(val => {
            const num = parseFloat(val);
            return isNaN(num) ? 0 : num;
          });

          let times = Array.from({ length: trial.time.length }, (_, i) => i + 1);
          let filteredValues = cleanedValues;

          const indicesInRange = times
            .map((t, i) => ({ time: t, index: i }))
            .filter(t => t.time >= timeStart && t.time <= timeEnd)
            .map(t => t.index);

          if (indicesInRange.length === 0) return;

          times = indicesInRange.map(i => times[i]);
          filteredValues = indicesInRange.map(i => cleanedValues[i]);

          let avgUnfiltered = filteredValues;
          let avgFiltered = [...avgUnfiltered];

          let normalizedFiltered = [...avgFiltered];
          let baselineAvg = 0;
          let isNormalized = false;

          if (baselineStart !== null && baselineEnd !== null && baselineStart <= baselineEnd) {
            const baselineIndices = times
              .map((t, i) => ({ time: t, index: i }))
              .filter(t => t.time >= baselineStart && t.time <= baselineEnd)
              .map(t => t.index);

            if (baselineIndices.length > 0) {
              const baselineValues = avgUnfiltered.filter((_, i) => baselineIndices.includes(i));
              baselineAvg = baselineValues.reduce((sum, val) => sum + val, 0) / baselineValues.length;

              if (baselineAvg !== 0) {
                normalizedFiltered = avgFiltered.map(y => 100 * (y - baselineAvg) / baselineAvg);
                isNormalized = true;
              }
            }
          }

          if (noiseFilter !== 'none') {
            if (noiseFilter === 'movingAverage') {
              normalizedFiltered = movingAverage(normalizedFiltered, windowSize);
            } else if (noiseFilter === 'savitzkyGolay') {
              normalizedFiltered = savitzkyGolay(normalizedFiltered, windowSize, polynomialOrder);
            } else if (noiseFilter === 'medianFilter') {
              normalizedFiltered = medianFilter(normalizedFiltered, windowSize);
            }
          }

          const finalData = noiseFilter !== 'none' ? normalizedFiltered : avgUnfiltered;

          const maxDeltaR = Math.max(...finalData);
          const maxIndex = finalData.indexOf(maxDeltaR);

          let riseTime = null;
          if (baselineEnd !== null && baselineEnd <= timeEnd) {
            const baselineEndIndex = times.findIndex(t => t >= baselineEnd);
            if (baselineEndIndex !== -1 && baselineEndIndex <= maxIndex) {
              riseTime = times[maxIndex] - times[baselineEndIndex];
            }
          }
          if (riseTime === null) {
            riseTime = times[maxIndex] - times[0];
          }

          let decayTime = null;
          const baselineThreshold = isNormalized ? 0 : baselineAvg;
          for (let i = maxIndex + 1; i < finalData.length; i++) {
            if (finalData[i] <= baselineThreshold) {
              decayTime = times[i] - times[maxIndex];
              break;
            }
          }
          if (decayTime === null) {
            decayTime = times[times.length - 1] - times[maxIndex];
          }

          let h0 = null;
          if ('H0' in trial.allColumns) {
            console.log(`Extracting H0 for file ${fileName}, column ${key}`);
            const h0Values = trial.allColumns['H0'];
            if (h0Values && h0Values.length > 0) {
              const slicedH0 = indicesInRange.map(i => h0Values[i]);
              const validH0Values = slicedH0.filter(val => {
                const num = parseFloat(val);
                return !isNaN(num) ? num : 0;
              });
              if (validH0Values.length > 0) {
                h0 = validH0Values.reduce((sum, val) => sum + val, 0) / validH0Values.length;
                console.log(`H0 mean for file ${fileName}, column ${key}:`, h0);
              }
            }
          }

          let t0 = null;
          if ('T0' in trial.allColumns) {
            console.log(`Extracting T0 for file ${fileName}, column ${key}`);
            const t0Values = trial.allColumns['T0'];
            if (t0Values && t0Values.length > 0) {
              const slicedT0 = indicesInRange.map(i => t0Values[i]);
              const validT0Values = slicedT0.filter(val => {
                const num = parseFloat(val);
                return !isNaN(num) ? num : 0;
              });
              if (validT0Values.length > 0) {
                t0 = validT0Values.reduce((sum, val) => sum + val, 0) / validT0Values.length;
                console.log(`T0 mean for file ${fileName}, column ${key}:`, t0);
              }
            }
          }

          parameters.push({
            chr: key,
            concentration: label,
            maxDeltaR,
            riseTime,
            decayTime,
            h0,
            t0,
          });
        });

        if (parameters.length > 0) {
          paramsByFile.push({
            fileName: `${fileName} (${label})`,
            parameters: parameters,
          });
        }
      });

      setParametersByFile(paramsByFile);
    }
    setShowTable(!showTable);
    setShowHumidityTable(false);
    setHumidityResults([]);
    setHumidityError(null);
  };

  const handleCalculateHumiditySensitivity = (humidityStart, humidityEnd) => {
    if (!plots || plots.length === 0) {
      alert('No data available to calculate humidity sensitivity.');
      return;
    }

    let hasH0 = false;
    for (const plot of plots) {
      for (const trials of Object.values(plot.fileGroups)) {
        if ('H0' in trials[0].allColumns) {
          hasH0 = true;
          break;
        }
      }
      if (hasH0) break;
    }

    if (!hasH0) {
      setHumidityError('Humidity data missing.');
      setHumidityResults([]);
      setShowHumidityTable(true);
      setShowTable(false);
      return;
    }

    const results = [];
    const concentrationToFileName = {};
    uploadedFileNames.forEach(fileName => {
      const concentrationMatch = fileName.match(/(\d+(\.\d+)?)(nL|uL|ppm)/);
      const concentration = concentrationMatch ? concentrationMatch[0] : 'unknown';
      concentrationToFileName[concentration] = fileName;
    });

    plots.forEach(plot => {
      const { key, fileGroups } = plot;
      const isSupportedColumn = key.startsWith('CHR') ||
        /^s\d{1,2}$/.test(key) ||
        /^Sensor\d{2}-dVal$/.test(key) ||
        /^Sensor\d{2}-DR\d{1,2}$/.test(key) ||
        /^S\d{1,2}$/.test(key);
      if (!isSupportedColumn) return;

      for (const [concentration, trials] of Object.entries(fileGroups)) {
        const valueArrays = trials
          .map(trial => trial.allColumns[key])
          .filter(arr => arr && arr.length > 0);
        if (valueArrays.length === 0) continue;

        // Convert string values to numbers, default to 0 if not a valid number
        const cleanedValueArrays = valueArrays.map(arr => arr.map(val => {
          const num = parseFloat(val);
          return isNaN(num) ? 0 : num;
        }));

        let times = Array.from({ length: trials[0].time.length }, (_, i) => i + 1);
        let filteredValueArrays = cleanedValueArrays;

        const indicesInRange = times
          .map((t, i) => ({ time: t, index: i }))
          .filter(t => t.time >= humidityStart && t.time <= humidityEnd)
          .map(t => t.index);

        if (indicesInRange.length < 2) {
          console.log(`Not enough data points in range ${humidityStart}-${humidityEnd} for ${key} in ${concentration}`);
          continue;
        }

        times = indicesInRange.map(i => times[i]);
        filteredValueArrays = cleanedValueArrays.map(arr =>
          indicesInRange.map(i => arr[i])
        );

        let avgR = mean(filteredValueArrays);

        if (noiseFilter !== 'none') {
          if (noiseFilter === 'movingAverage') {
            avgR = movingAverage(avgR, windowSize);
          } else if (noiseFilter === 'savitzkyGolay') {
            avgR = savitzkyGolay(avgR, windowSize, polynomialOrder);
          } else if (noiseFilter === 'medianFilter') {
            avgR = medianFilter(avgR, windowSize);
          }
        }

        let avgH0 = null;
        if ('H0' in trials[0].allColumns) {
          const h0Values = trials
            .map(trial => trial.allColumns['H0'])
            .filter(arr => arr && arr.length > 0)
            .map(arr => indicesInRange.map(i => arr[i]))
            .filter(arr => arr.length > 0);
          if (h0Values.length > 0) {
            const validH0Values = h0Values.map(arr => arr.filter(val => {
              const num = parseFloat(val);
              return !isNaN(num) ? num : 0;
            }));
            if (validH0Values.length > 0 && validH0Values.every(arr => arr.length > 0)) {
              avgH0 = mean(validH0Values);
            }
          }
        }

        if (avgH0 === null) {
          console.log(`No valid H₀ data for concentration ${concentration}, column ${key}`);
          continue;
        }

        const rStart = avgR[0];
        const rEnd = avgR[avgR.length - 1];
        let deltaR_R = null;
        if (rStart !== 0) {
          deltaR_R = ((rEnd - rStart) / rStart) * 100; // % Resistance Change
        }

        const hStart = avgH0[0];
        const hEnd = avgH0[avgH0.length - 1];
        const deltaH = hEnd - hStart;

        let slope = null;
        if (deltaR_R !== null && deltaH !== 0) {
          slope = deltaR_R / deltaH;
        }

        results.push({
          chr: key,
          concentration,
          slope,
          originalFileName: concentrationToFileName[concentration] || concentration,
        });
      }
    });

    setHumidityResults(results);
    setHumidityError(null);
    setShowHumidityTable(true);
    setShowTable(false);
  };

  const getBaselineResistanceData = () => {
    const baselineData = [];

    const start = parseInt(baselineWindowStart, 10);
    const end = parseInt(baselineWindowEnd, 10);

    if (isNaN(start) || isNaN(end) || start < 0 || end < start) {
      console.log('Invalid baseline time window');
      return baselineData;
    }

    plots.forEach(plot => {
      const { key, fileGroups } = plot;
      const isSupportedColumn = key.startsWith('CHR') ||
        /^s\d{1,2}$/.test(key) ||
        /^Sensor\d{2}-dVal$/.test(key) ||
        /^Sensor\d{2}-DR\d{1,2}$/.test(key) ||
        /^S\d{1,2}$/.test(key);
      if (!isSupportedColumn) return;

      for (const [concentration, trials] of Object.entries(fileGroups)) {
        const valueArrays = trials
          .map(trial => trial.allColumns[key])
          .filter(arr => arr && arr.length > 0);
        if (valueArrays.length === 0) continue;

        const cleanedValueArrays = valueArrays.map(arr => arr.map(val => {
          const num = parseFloat(val);
          return isNaN(num) ? 0 : num;
        }));

        let times = Array.from({ length: trials[0].time.length }, (_, i) => i + 1);
        const indicesInRange = times
          .map((t, i) => ({ time: t, index: i }))
          .filter(t => t.time >= start && t.time <= end)
          .map(t => t.index);

        if (indicesInRange.length === 0) {
          console.log(`No data points in baseline window ${start}-${end} for ${key} in ${concentration}`);
          continue;
        }

        const baselineValues = cleanedValueArrays.map(arr => {
          const valuesInRange = indicesInRange.map(i => arr[i]);
          return valuesInRange.reduce((sum, val) => sum + val, 0) / valuesInRange.length;
        });

        const baselineResistance = baselineValues.reduce((sum, val) => sum + val, 0) / baselineValues.length;

        baselineData.push({
          chr: `${key} (${concentration})`,
          resistance: baselineResistance,
        });
      }
    });

    return baselineData;
  };

  const handleToggleBaselineChart = () => {
    if (!showBaselineChart) {
      const start = parseInt(baselineWindowStart, 10);
      const end = parseInt(baselineWindowEnd, 10);

      if (baselineWindowStart === '' || baselineWindowEnd === '') {
        alert('Please specify both start and end time counts for the baseline window.');
        return;
      }

      if (isNaN(start) || isNaN(end) || start < 0 || end <= start) {
        alert('Please enter valid start and end time counts (start >= 0, end > start).');
        return;
      }
    }

    setShowBaselineChart(prev => !prev);
  };

  const baselineResistanceData = getBaselineResistanceData();

  console.log('Current state:', { tabValue, plots, timeStart, timeEnd, noiseFilter, windowSize, polynomialOrder, baselineStart, baselineEnd, showRaw });

  return (
    <ThemeProvider theme={theme}>
      <Box sx={{ flexGrow: 1, bgcolor: '#f0f2f5', minHeight: '100vh' }}>
        <Navbar value={tabValue} onChange={handleTabChange} />
        <Box
          sx={{
            p: 4,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            width: '100%',
            boxSizing: 'border-box',
          }}
        >
          {(tabValue === 0 || tabValue === 1) && (
            <Box display="flex" flexDirection="column" alignItems="center" mb={3} width="100%">
              <UploadButton onFileUpload={handleFileUpload} />
              {uploadedFileNames.length > 0 && (
                <Box mt={2} display="flex" flexDirection="column" alignItems="center">
                  {uploadedFileNames.map((fileName, index) => (
                    <Box key={index} display="flex" alignItems="center" mt={1}>
                      <FontAwesomeIcon
                        icon={faFileCsv}
                        style={{ color: '#00DE93', marginRight: 8, fontSize: 24 }}
                      />
                      <Typography sx={{ color: '#555' }}>
                        {`${fileName} (${fileLabelMap[fileName] || ''})`}
                      </Typography>
                    </Box>
                  ))}
                </Box>
              )}
            </Box>
          )}
          {(tabValue === 0 || tabValue === 1) && (
            <>
              {plots.length > 0 ? (
                <>
                  {tabValue === 0 && (
                    <Box display="flex" flexDirection="column" alignItems="center" width="100%">
                      <Box
                        display="flex"
                        alignItems="center"
                        flexWrap="wrap"
                        gap={1}
                        sx={{
                          backgroundColor: '#f5f5f5',
                          padding: 2,
                          borderRadius: '8px',
                          boxShadow: 2,
                          justifyContent: 'center',
                          width: 'auto',
                          mb: 2,
                        }}
                      >
                        <TextField
                          label="Baseline Start Time"
                          type="number"
                          value={baselineWindowStart}
                          onChange={(e) => setBaselineWindowStart(e.target.value)}
                          size="small"
                          sx={{
                            width: 150,
                            '& .MuiInputBase-root': {
                              backgroundColor: '#fff',
                              borderRadius: '4px',
                            },
                            '& .MuiInputLabel-root': {
                              fontWeight: 500,
                              color: '#555',
                            },
                          }}
                          InputProps={{ inputProps: { min: 0 } }}
                        />
                        <TextField
                          label="Baseline End Time"
                          type="number"
                          value={baselineWindowEnd}
                          onChange={(e) => setBaselineWindowEnd(e.target.value)}
                          size="small"
                          sx={{
                            width: 150,
                            '& .MuiInputBase-root': {
                              backgroundColor: '#fff',
                              borderRadius: '4px',
                            },
                            '& .MuiInputLabel-root': {
                              fontWeight: 500,
                              color: '#555',
                            },
                          }}
                          InputProps={{ inputProps: { min: 0 } }}
                        />
                        <BaselineButton onClick={handleToggleBaselineChart}>
                          {showBaselineChart ? 'Show Plots' : 'Show Baseline Chart'}
                        </BaselineButton>
                      </Box>
                      {showBaselineChart ? (
                        isPlotlyLoaded ? (
                          <BaselineResistanceChart
                            data={baselineResistanceData}
                            startTime={baselineWindowStart}
                            endTime={baselineWindowEnd}
                          />
                        ) : (
                          <Typography sx={{ mt: 4, color: '#555' }}>
                            Loading Plotly chart...
                          </Typography>
                        )
                      ) : (
                        <Box display="flex" justifyContent="center" width="100%">
                          <PlotGrid
                            plots={plots}
                            timeStart={normalizationApplied ? timeStart : null}
                            timeEnd={normalizationApplied ? timeEnd : null}
                            noiseFilter={normalizationApplied ? noiseFilter : 'none'}
                            windowSize={windowSize}
                            polynomialOrder={polynomialOrder}
                            baselineStart={normalizationApplied ? baselineStart : null}
                            baselineEnd={normalizationApplied ? baselineEnd : null}
                            showRaw={showRaw}
                          />
                        </Box>
                      )}
                    </Box>
                  )}
                  {tabValue === 1 && (
                    <Box display="flex" flexDirection="column" alignItems="center" width="100%">
                      <Box display="flex" justifyContent="center" mb={3} width="100%">
                        <TimeFilter
                          onFilter={handleFilter}
                          onReset={handleReset}
                          initialWindowSize={windowSizeInput}
                          initialPolynomialOrder={polynomialOrderInput}
                          onToggleRaw={handleToggleRaw}
                          showRaw={showRaw}
                          startInput={startInput}
                          setStartInput={setStartInput}
                          endInput={endInput}
                          setEndInput={setEndInput}
                          filterTypeInput={filterTypeInput}
                          setFilterTypeInput={setFilterTypeInput}
                          windowSizeInput={windowSizeInput}
                          setWindowSizeInput={setWindowSizeInput}
                          polynomialOrderInput={polynomialOrderInput}
                          setPolynomialOrderInput={setPolynomialOrderInput}
                          baselineStartInput={baselineStartInput}
                          setBaselineStartInput={setBaselineStartInput}
                          baselineEndInput={baselineEndInput}
                          setBaselineEndInput={setBaselineEndInput}
                          onExtractParams={handleExtractParamsToggle}
                          showTable={showTable}
                          onCalculateHumiditySensitivity={handleCalculateHumiditySensitivity}
                        />
                      </Box>
                      {showTable ? (
                        <ParametersTable parametersByFile={parametersByFile} />
                      ) : showHumidityTable ? (
                        <HumiditySensitivityTable results={humidityResults} errorMessage={humidityError} />
                      ) : (
                        <Box display="flex" justifyContent="center" width="100%">
                          <PlotGrid
                            plots={plots}
                            timeStart={timeStart}
                            timeEnd={timeEnd}
                            noiseFilter={noiseFilter}
                            windowSize={windowSize}
                            polynomialOrder={polynomialOrder}
                            baselineStart={baselineStart}
                            baselineEnd={baselineEnd}
                            showRaw={showRaw}
                          />
                        </Box>
                      )}
                    </Box>
                  )}
                </>
              ) : (
                <Typography sx={{ mt: 4, color: '#555' }}>
                  Please upload data files to view plots.
                </Typography>
              )}
            </>
          )}
          {tabValue === 2 && (
            <Documents />
          )}
        </Box>
      </Box>
    </ThemeProvider>
  );
}

export default App;