/* global Plotly */
import React, { useEffect, useRef } from 'react';
import { Box, useTheme } from '@mui/material';

function BaselineResistanceChart({ data, startTime, endTime }) {
  const plotRef = useRef(null);
  const theme = useTheme(); // Access the Material-UI theme

  useEffect(() => {
    if (!data || data.length === 0 || !window.Plotly) {
      console.log('Plotly not loaded or no data available');
      return;
    }

    const labels = data.map(item => item.chr);
    const values = data.map(item => item.resistance);
    const colors = values.map(value => {
      if (value >= 2_000_000) return '#f44336'; // Red for ≥ 2 MΩ
      if (value >= 1_000_000) return '#ffeb3b'; // Yellow for ≥ 1 MΩ
      return theme.palette.primary.main; // Theme primary color for < 1 MΩ
    });

    const plotData = [
      {
        x: labels,
        y: values,
        type: 'bar',
        marker: {
          color: colors,
          line: {
            color: colors,
            width: 1,
          },
        },
      },
    ];

    const layout = {
      title: {
        text: `Baseline Resistance (Average from t = ${startTime} to t = ${endTime})`,
        font: {
          size: 18,
          color: '#333',
        },
        x: 0.5,
        xanchor: 'center',
      },
      xaxis: {
        title: 'Channel',
        tickangle: 45,
      },
      yaxis: {
        title: 'Resistance (Ω)',
        tickformat: ',.2s', // Format large numbers (e.g., 1.5M)
        tickmode: 'linear',
        tick0: 0,
        dtick: 500_000, // Step of 0.5 MΩ
      },
      height: 400,
      margin: {
        l: 50,
        r: 50,
        t: 50,
        b: 100,
      },
      showlegend: false,
    };

    const config = {
      displayModeBar: false, // Hide the Plotly toolbar
    };

    Plotly.newPlot(plotRef.current, plotData, layout, config);

    // Cleanup on unmount
    return () => {
      if (plotRef.current) {
        Plotly.purge(plotRef.current);
      }
    };
  }, [data, startTime, endTime, theme]); // Add theme to dependencies

  if (!data || data.length === 0) return null;

  return (
    <Box sx={{ mt: 4, width: '100%', maxWidth: 800, mx: 'auto' }}>
      <div ref={plotRef} />
    </Box>
  );
}

export default BaselineResistanceChart;